insert into finlab.exam_bank(module_id,bank_version,variant,public_questions,private_questions) values ('m1',2,0,'[{"id":"m1-b2-v0-q1","competencyIds":["interest-rates","compounding"],"difficulty":1,"exercise":{"id":"m1-b2-v0-q1","kind":"numeric","templateId":"simple-compound","variantId":"bank-v1:simple-compound:192023:1","seed":192023,"difficulty":1,"competencyIds":["interest-rates","compounding"],"skills":["mathematics","literacy"],"unit":"currency","prompt":"Две учебные схемы для 47 000 ₽ на 2 г. под 5% годовых: простые проценты без капитализации и сложные с ежегодной капитализацией. На сколько рублей итог сложной схемы выше? Взносов, налогов и комиссий нет.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m1-b2-v0-q2","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v0-q2","kind":"numeric","templateId":"real-return","variantId":"bank-v1:real-return:192124:2","seed":192124,"difficulty":2,"competencyIds":["inflation","returns"],"skills":["mathematics","investments","literacy"],"unit":"percent","prompt":"За один и тот же учебный год номинальная доходность составила 11%, изменение уровня цен — 6%. Определите точную реальную доходность по отношению к покупательной способности в начале года.","instruction":"Ответ в процентах, не в долях: например 7,5 или 7,5%. Округлите только итог до двух знаков. Данные учебные.","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m1-b2-v0-q3","competencyIds":["financial-literacy"],"difficulty":1,"exercise":{"id":"m1-b2-v0-q3","kind":"numeric","prompt":"Учебный месячный бюджет: денежный доход 60000 ₽, все расходы 36000 ₽. Какова норма сбережений в процентах дохода?","unit":"percent","absoluteTolerance":0.005,"skills":["literacy","mathematics"]}},{"id":"m1-b2-v0-q4","competencyIds":["financial-literacy"],"difficulty":1,"exercise":{"id":"m1-b2-v0-q4","kind":"choice","prompt":"Что относится к обязательствам?","options":[{"id":"2","label":"Рыночная стоимость квартиры"},{"id":"0","label":"Деньги на текущем счёте"},{"id":"1","label":"Остаток ипотечного кредита"}],"multiple":false,"skills":["literacy"]}},{"id":"m1-b2-v0-q5","competencyIds":["financial-literacy"],"difficulty":1,"exercise":{"id":"m1-b2-v0-q5","kind":"scenario","prompt":"Анна переводит 10 000 ₽ с текущего счёта на собственный вклад. Что происходит с её совокупными активами в момент перевода, без комиссий?","options":[{"id":"0","label":"Увеличиваются на 10 000 ₽"},{"id":"1","label":"Не меняются"},{"id":"2","label":"Уменьшаются на 10 000 ₽"}],"multiple":false,"skills":["literacy"]}},{"id":"m1-b2-v0-q6","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v0-q6","kind":"boolean","prompt":"Если номинальная доходность равна инфляции за тот же период, реальная доходность до расходов равна нулю.","skills":["literacy"]}},{"id":"m1-b2-v0-q7","competencyIds":["financial-literacy"],"difficulty":2,"exercise":{"id":"m1-b2-v0-q7","kind":"ordering","prompt":"Расположите шаги составления личного финансового баланса.","skills":["mathematics"],"items":[{"id":"r2","label":"Выбрать единую дату оценки"},{"id":"v4","label":"Посчитать остаток обязательств на эту дату"},{"id":"c9","label":"Вычесть обязательства из активов"},{"id":"u7","label":"Оценить принадлежащие активы на эту дату"}]}},{"id":"m1-b2-v0-q8","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v0-q8","kind":"scenario","prompt":"Вклад за год дал 6% до расходов, цены за тот же год выросли на 9%. Как изменится покупательная способность капитала при отсутствии взносов?","options":[{"id":"k3","label":"Увеличится на 6%"},{"id":"k8","label":"Снизится"},{"id":"k6","label":"Останется прежней"}],"skills":["literacy"]}}]'::jsonb,'[{"id":"m1-b2-v0-q1","exercise":{"id":"m1-b2-v0-q1","kind":"numeric","templateId":"simple-compound","variantId":"bank-v1:simple-compound:192023:1","seed":192023,"difficulty":1,"competencyIds":["interest-rates","compounding"],"skills":["mathematics","literacy"],"unit":"currency","expected":117.49999999999272,"prompt":"Две учебные схемы для 47 000 ₽ на 2 г. под 5% годовых: простые проценты без капитализации и сложные с ежегодной капитализацией. На сколько рублей итог сложной схемы выше? Взносов, налогов и комиссий нет.","hint":"Сначала посчитайте два итога отдельно: P(1 + rn) и P(1 + r)ⁿ. В ответе нужна разность итоговых сумм, а не вся сумма процентов.","explanation":"1. Простые проценты: 47 000 × (1 + 5 / 100 × 2) = 51 700 ₽. 2. Сложные: 47 000 × (1 + 5 / 100)^2 = 51 817,5 ₽. 3. Разность до округления: 117,5 ₽.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0},"competencyIds":["interest-rates","compounding"],"difficulty":1},{"id":"m1-b2-v0-q2","exercise":{"id":"m1-b2-v0-q2","kind":"numeric","templateId":"real-return","variantId":"bank-v1:real-return:192124:2","seed":192124,"difficulty":2,"competencyIds":["inflation","returns"],"skills":["mathematics","investments","literacy"],"unit":"percent","expected":4.716981132075482,"prompt":"За один и тот же учебный год номинальная доходность составила 11%, изменение уровня цен — 6%. Определите точную реальную доходность по отношению к покупательной способности в начале года.","hint":"Сравните множитель роста капитала с множителем изменения цен: (1 + rном) / (1 + π) − 1. Простое вычитание ставок даёт только приближение.","explanation":"1. Множитель капитала: 1 + 11 / 100. 2. Множитель цен: 1 + 6 / 100. 3. rреал = [(1 + 11 / 100) / (1 + 6 / 100) − 1] × 100% = 4,72%. Отрицательный результат означает снижение покупательной способности.","instruction":"Ответ в процентах, не в долях: например 7,5 или 7,5%. Округлите только итог до двух знаков. Данные учебные.","absoluteTolerance":0.005,"relativeTolerance":0},"competencyIds":["inflation","returns"],"difficulty":2},{"id":"m1-b2-v0-q3","competencyIds":["financial-literacy"],"difficulty":1,"exercise":{"id":"m1-b2-v0-q3","kind":"numeric","prompt":"Учебный месячный бюджет: денежный доход 60000 ₽, все расходы 36000 ₽. Какова норма сбережений в процентах дохода?","expected":40,"unit":"percent","absoluteTolerance":0.005,"skills":["literacy","mathematics"],"hint":"Вычтите расходы из дохода и разделите остаток на доход.","explanation":"1. Сбережения = 60000 − 36000 = 24000 ₽. 2. Норма сбережений = (24000 / 60000) × 100% = 40.00%. База — весь денежный доход."}},{"id":"m1-b2-v0-q4","exercise":{"id":"m1-b2-v0-q4","kind":"choice","prompt":"Что относится к обязательствам?","options":[{"id":"2","label":"Рыночная стоимость квартиры"},{"id":"0","label":"Деньги на текущем счёте"},{"id":"1","label":"Остаток ипотечного кредита"}],"correct":["1"],"multiple":false,"hint":"Ищите сумму, которую нужно вернуть, а не ресурс, которым вы владеете.","explanation":"Остаток ипотечного кредита — долг. Счёт и квартира являются активами; наличие долга не отменяет существование актива.","skills":["literacy"]},"competencyIds":["financial-literacy"],"difficulty":1},{"id":"m1-b2-v0-q5","exercise":{"id":"m1-b2-v0-q5","kind":"scenario","prompt":"Анна переводит 10 000 ₽ с текущего счёта на собственный вклад. Что происходит с её совокупными активами в момент перевода, без комиссий?","options":[{"id":"0","label":"Увеличиваются на 10 000 ₽"},{"id":"1","label":"Не меняются"},{"id":"2","label":"Уменьшаются на 10 000 ₽"}],"correct":["1"],"multiple":false,"hint":"Оба счёта принадлежат одному человеку.","explanation":"Один актив уменьшается на 10 000 ₽, другой увеличивается на ту же сумму. Совокупные активы и чистый капитал не меняются.","skills":["literacy"]},"competencyIds":["financial-literacy"],"difficulty":1},{"id":"m1-b2-v0-q6","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v0-q6","kind":"boolean","prompt":"Если номинальная доходность равна инфляции за тот же период, реальная доходность до расходов равна нулю.","correct":true,"explanation":"По точной формуле Фишера (1+r)/(1+π)−1 при r=π отношение равно 1, поэтому реальный прирост равен 0. Периоды и база расчёта должны совпадать.","hint":"Согласуйте экономический смысл и дату денежного потока.","skills":["literacy"]}},{"id":"m1-b2-v0-q7","exercise":{"id":"m1-b2-v0-q7","kind":"ordering","prompt":"Расположите шаги составления личного финансового баланса.","skills":["mathematics"],"items":[{"id":"r2","label":"Выбрать единую дату оценки"},{"id":"v4","label":"Посчитать остаток обязательств на эту дату"},{"id":"c9","label":"Вычесть обязательства из активов"},{"id":"u7","label":"Оценить принадлежащие активы на эту дату"}],"correctOrder":["r2","u7","v4","c9"],"hint":"Сначала определите исходные данные и базу сравнения, затем выполняйте расчёт.","explanation":"1. Баланс — снимок на одну дату. 2. На ней оценивают активы. 3. На той же дате фиксируют долги. 4. Чистый капитал равен активам минус обязательства. Оценки разных дат смешивать нельзя."},"competencyIds":["financial-literacy"],"difficulty":2},{"id":"m1-b2-v0-q8","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v0-q8","kind":"scenario","prompt":"Вклад за год дал 6% до расходов, цены за тот же год выросли на 9%. Как изменится покупательная способность капитала при отсутствии взносов?","options":[{"id":"k3","label":"Увеличится на 6%"},{"id":"k8","label":"Снизится"},{"id":"k6","label":"Останется прежней"}],"correct":["k8"],"skills":["literacy"],"hint":"Сравните факторы роста денег и цен.","explanation":"1. Фактор роста вклада 1,06. 2. Фактор роста цен 1,09. 3. Реальная доходность = 1,06/1,09−1 ≈ −2,75%. Денег стало больше, но на них можно купить меньше."}}]'::jsonb) on conflict(module_id,bank_version,variant) do nothing;
