relativeTolerance":0},"competencyIds":["inflation","returns"],"difficulty":2},{"id":"m1-b2-v4-q3","competencyIds":["financial-literacy"],"difficulty":1,"exercise":{"id":"m1-b2-v4-q3","kind":"numeric","prompt":"Учебный месячный бюджет: денежный доход 80000 ₽, все расходы 44000 ₽. Какова норма сбережений в процентах дохода?","expected":45,"unit":"percent","absoluteTolerance":0.005,"skills":["literacy","mathematics"],"hint":"Вычтите расходы из дохода и разделите остаток на доход.","explanation":"1. Сбережения = 80000 − 44000 = 36000 ₽. 2. Норма сбережений = (36000 / 80000) × 100% = 45.00%. База — весь денежный доход."}},{"id":"m1-b2-v4-q4","exercise":{"id":"m1-b2-v4-q4","kind":"choice","prompt":"Что относится к обязательствам?","options":[{"id":"1","label":"Остаток ипотечного кредита"},{"id":"0","label":"Деньги на текущем счёте"},{"id":"2","label":"Рыночная стоимость квартиры"}],"correct":["1"],"multiple":false,"hint":"Ищите сумму, которую нужно вернуть, а не ресурс, которым вы владеете.","explanation":"Остаток ипотечного кредита — долг. Счёт и квартира являются активами; наличие долга не отменяет существование актива.","skills":["literacy"]},"competencyIds":["financial-literacy"],"difficulty":1},{"id":"m1-b2-v4-q5","exercise":{"id":"m1-b2-v4-q5","kind":"scenario","prompt":"Анна переводит 10 000 ₽ с текущего счёта на собственный вклад. Что происходит с её совокупными активами в момент перевода, без комиссий?","options":[{"id":"2","label":"Уменьшаются на 10 000 ₽"},{"id":"1","label":"Не меняются"},{"id":"0","label":"Увеличиваются на 10 000 ₽"}],"correct":["1"],"multiple":false,"hint":"Оба счёта принадлежат одному человеку.","explanation":"Один актив уменьшается на 10 000 ₽, другой увеличивается на ту же сумму. Совокупные активы и чистый капитал не меняются.","skills":["literacy"]},"competencyIds":["financial-literacy"],"difficulty":1},{"id":"m1-b2-v4-q6","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v4-q6","kind":"boolean","prompt":"Если номинальная доходность равна инфляции за тот же период, реальная доходность до расходов равна нулю.","correct":true,"explanation":"По точной формуле Фишера (1+r)/(1+π)−1 при r=π отношение равно 1, поэтому реальный прирост равен 0. Периоды и база расчёта должны совпадать.","hint":"Согласуйте экономический смысл и дату денежного потока.","skills":["literacy"]}},{"id":"m1-b2-v4-q7","exercise":{"id":"m1-b2-v4-q7","kind":"ordering","prompt":"Расположите шаги составления личного финансового баланса.","skills":["mathematics"],"items":[{"id":"v4","label":"Посчитать остаток обязательств на эту дату"},{"id":"c9","label":"Вычесть обязательства из активов"},{"id":"r2","label":"Выбрать единую дату оценки"},{"id":"u7","label":"Оценить принадлежащие активы на эту дату"}],"correctOrder":["r2","u7","v4","c9"],"hint":"Сначала определите исходные данные и базу сравнения, затем выполняйте расчёт.","explanation":"1. Баланс — снимок на одну дату. 2. На ней оценивают активы. 3. На той же дате фиксируют долги. 4. Чистый капитал равен активам минус обязательства. Оценки разных дат смешивать нельзя."},"competencyIds":["financial-literacy"],"difficulty":2},{"id":"m1-b2-v4-q8","competencyIds":["inflation","returns"],"difficulty":2,"exercise":{"id":"m1-b2-v4-q8","kind":"scenario","prompt":"Вклад за год дал 6% до расходов, цены за тот же год выросли на 9%. Как изменится покупательная способность капитала при отсутствии взносов?","options":[{"id":"k3","label":"Увеличится на 6%"},{"id":"k6","label":"Останется прежней"},{"id":"k8","label":"Снизится"}],"correct":["k8"],"skills":["literacy"],"hint":"Сравните факторы роста денег и цен.","explanation":"1. Фактор роста вклада 1,06. 2. Фактор роста цен 1,09. 3. Реальная доходность = 1,06/1,09−1 ≈ −2,75%. Денег стало больше, но на них можно купить меньше."}}]'::jsonb) on conflict(module_id,bank_version,variant) do nothing;
