insert into finlab.exam_bank(module_id,bank_version,variant,public_questions,private_questions) values ('m2',2,2,'[{"id":"m2-b2-v2-q1","competencyIds":["present-value","discounting"],"difficulty":3,"exercise":{"id":"m2-b2-v2-q1","kind":"numeric","templateId":"present-value","variantId":"bank-v1:present-value:307864:3","seed":307864,"difficulty":3,"competencyIds":["present-value","discounting"],"skills":["mathematics"],"unit":"currency","prompt":"Через 8 г. ожидается единственный платёж 90 000 ₽. Эффективная годовая ставка дисконтирования — -5%. Определите стоимость этого платежа сегодня; промежуточных потоков нет.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m2-b2-v2-q2","competencyIds":["future-value","compounding"],"difficulty":3,"exercise":{"id":"m2-b2-v2-q2","kind":"numeric","templateId":"future-value","variantId":"bank-v1:future-value:307965:3","seed":307965,"difficulty":3,"competencyIds":["future-value","compounding"],"skills":["mathematics"],"unit":"currency","prompt":"Учебный вклад: начальная сумма 72 000 ₽, эффективная ставка 12% в год, срок 8 г. Капитализация ежегодная; взносов и снятий нет. Какова будущая стоимость?","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m2-b2-v2-q3","competencyIds":["discounting","present-value"],"difficulty":2,"exercise":{"id":"m2-b2-v2-q3","kind":"numeric","templateId":"discount-two-flows","variantId":"bank-v1:discount-two-flows:308067:2","seed":308067,"difficulty":2,"competencyIds":["discounting","present-value"],"skills":["mathematics"],"unit":"currency","prompt":"Учебный контракт выплатит 30 000 ₽ в конце первого года и 58 000 ₽ в конце второго. Ставка дисконтирования — 11% в год. Найдите общую приведённую стоимость двух поступлений на дату 0. Начальное вложение здесь не задано.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m2-b2-v2-q4","competencyIds":["npv","discounting"],"difficulty":2,"exercise":{"id":"m2-b2-v2-q4","kind":"numeric","templateId":"npv","variantId":"bank-v1:npv:308171:2","seed":308171,"difficulty":2,"competencyIds":["npv","discounting"],"skills":["mathematics"],"unit":"currency","prompt":"Учебный проект требует 67 000 ₽ сегодня (дата 0), затем приносит потоки в конце соответствующих лет: год 1: 69 000 ₽; год 2: 43 000 ₽; год 3: 40 000 ₽. Ставка дисконтирования — 9% в год. Рассчитайте NPV; иных потоков нет.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m2-b2-v2-q5","competencyIds":["irr","discounting"],"difficulty":3,"exercise":{"id":"m2-b2-v2-q5","kind":"numeric","templateId":"irr","variantId":"bank-v1:irr:308265:3","seed":308265,"difficulty":3,"competencyIds":["irr","discounting"],"skills":["mathematics"],"unit":"percent","prompt":"Обычный учебный инвестиционный поток: -86 000 ₽ сегодня; год 1: 48 000 ₽; год 2: 74 000 ₽. Все будущие поступления в конце года, промежуточные потоки явно указаны. Найдите годовую IRR — ставку, при которой NPV равна нулю. Можно использовать финансовый калькулятор.","instruction":"Ответ в процентах, не в долях: например 7,5 или 7,5%. Округлите только итог до двух знаков. Данные учебные.","absoluteTolerance":0.005,"relativeTolerance":0}},{"id":"m2-b2-v2-q6","competencyIds":["npv","discounting"],"difficulty":2,"exercise":{"id":"m2-b2-v2-q6","kind":"scenario","prompt":"У независимого учебного проекта NPV при корректной требуемой доходности равна +12 000 ₽. Какой вывод соответствует критерию NPV при прочих равных?","options":[{"id":"h2","label":"Проект гарантирует отсутствие любых рисков"},{"id":"h8","label":"Проект создаёт стоимость сверх требуемой доходности"},{"id":"h5","label":"IRR обязана равняться ровно нулю"}],"skills":["mathematics"]}},{"id":"m2-b2-v2-q7","competencyIds":["irr","npv"],"difficulty":2,"exercise":{"id":"m2-b2-v2-q7","kind":"boolean","prompt":"У любого набора денежных потоков обязательно существует ровно одна IRR.","skills":["literacy"]}},{"id":"m2-b2-v2-q8","competencyIds":["discounting","npv"],"difficulty":2,"exercise":{"id":"m2-b2-v2-q8","kind":"ordering","prompt":"Расположите шаги корректного расчёта NPV.","skills":["mathematics"],"items":[{"id":"v4","label":"Сложить приведённые потоки с начальным отрицательным вложением"},{"id":"c9","label":"Разместить все денежные потоки по датам, включая вложение в момент 0"},{"id":"r2","label":"Выбрать ставку за тот же период и согласовать предположения"},{"id":"u7","label":"Дисконтировать каждый будущий поток к моменту 0"}]}}]'::jsonb,'[{"id":"m2-b2-v2-q1","exercise":{"id":"m2-b2-v2-q1","kind":"numeric","templateId":"present-value","variantId":"bank-v1:present-value:307864:3","seed":307864,"difficulty":3,"competencyIds":["present-value","discounting"],"skills":["mathematics"],"unit":"currency","expected":135660.57925759844,"prompt":"Через 8 г. ожидается единственный платёж 90 000 ₽. Эффективная годовая ставка дисконтирования — -5%. Определите стоимость этого платежа сегодня; промежуточных потоков нет.","hint":"Дисконтирование переносит будущий платёж к сегодняшней дате: разделите его на накопленный множитель (1 + r)ⁿ. При отрицательной ставке PV может превышать будущую сумму.","explanation":"1. Ставка в долях: -5 / 100. 2. PV = 90 000 / (1 + -5 / 100)^8. 3. Сегодняшняя стоимость: 135 660,58 ₽. Годовая ставка согласована со сроком в годах.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0},"competencyIds":["present-value","discounting"],"difficulty":3},{"id":"m2-b2-v2-q2","exercise":{"id":"m2-b2-v2-q2","kind":"numeric","templateId":"future-value","variantId":"bank-v1:future-value:307965:3","seed":307965,"difficulty":3,"competencyIds":["future-value","compounding"],"skills":["mathematics"],"unit":"currency","expected":178269.3486932263,"prompt":"Учебный вклад: начальная сумма 72 000 ₽, эффективная ставка 12% в год, срок 8 г. Капитализация ежегодная; взносов и снятий нет. Какова будущая стоимость?","hint":"При ежегодной капитализации каждый следующий год работает и исходная сумма, и уже начисленный процент. Переведите процентную ставку в долю и возведите множитель роста в степень срока.","explanation":"1. Годовой множитель роста: 1 + 12 / 100 = 1,12. 2. FV = 72 000 × (1 + 12 / 100)^8. 3. Будущая стоимость равна 178 269,35 ₽. Промежуточные множители не округляем.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0},"competencyIds":["future-value","compounding"],"difficulty":3},{"id":"m2-b2-v2-q3","exercise":{"id":"m2-b2-v2-q3","kind":"numeric","templateId":"discount-two-flows","variantId":"bank-v1:discount-two-flows:308067:2","seed":308067,"difficulty":2,"competencyIds":["discounting","present-value"],"skills":["mathematics"],"unit":"currency","expected":74101.1281551822,"prompt":"Учебный контракт выплатит 30 000 ₽ в конце первого года и 58 000 ₽ в конце второго. Ставка дисконтирования — 11% в год. Найдите общую приведённую стоимость двух поступлений на дату 0. Начальное вложение здесь не задано.","hint":"Каждый поток нужно дисконтировать на его собственный срок. Только после приведения обоих потоков к дате 0 можно сложить их стоимости.","explanation":"1. PV первого платежа = 30 000 / (1 + 11 / 100) = 27 027,03 ₽. 2. PV второго = 58 000 / (1 + 11 / 100)² = 47 074,1 ₽. 3. Складываем неокруглённые PV: 74 101,13 ₽. Это PV поступлений, а не NPV проекта.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0},"competencyIds":["discounting","present-value"],"difficulty":2},{"id":"m2-b2-v2-q4","exercise":{"id":"m2-b2-v2-q4","kind":"numeric","templateId":"npv","variantId":"bank-v1:npv:308171:2","seed":308171,"difficulty":2,"competencyIds":["npv","discounting"],"skills":["mathematics"],"unit":"currency","expected":63382.33120648264,"prompt":"Учебный проект требует 67 000 ₽ сегодня (дата 0), затем приносит потоки в конце соответствующих лет: год 1: 69 000 ₽; год 2: 43 000 ₽; год 3: 40 000 ₽. Ставка дисконтирования — 9% в год. Рассчитайте NPV; иных потоков нет.","hint":"Приведите каждый будущий поток к дате 0 и сложите результаты. Начальное вложение происходит уже сегодня: включите его со знаком минус без дисконтирования.","explanation":"1. Денежный поток на дате 0: -67 000 ₽. 2. PV поступлений = 69 000 / (1 + 9 / 100)^1 + 43 000 / (1 + 9 / 100)^2 + 40 000 / (1 + 9 / 100)^3. 3. NPV = -67 000 + PV поступлений = 63 382,33 ₽. Положительный NPV соответствует превышению требуемой доходности в рамках заданных предположений.","instruction":"Ответ в рублях. Округлите итог до двух знаков; можно ввести 1 234,56 или 1 234,56 ₽. Все суммы и ставки — учебные предположения.","currency":"RUB","absoluteTolerance":0.005,"relativeTolerance":0},"competencyIds":["npv","discounting"],"difficulty":2},{"id":"m2-b2-v2-q5","exercise":{"id":"m2-b2-v2-q5","kind":"numeric","templateId":"irr","variantId":"bank-v1:irr:308265:3","seed":308265,"difficulty":3,"competencyIds":["irr","discounting"],"skills":["mathematics"],"unit":"percent","expected":24.775188835621066,"prompt":"Обычный учебный инвестиционный поток: -86 000 ₽ сегодня; год 1: 48 000 ₽; год 2: 74 00